348	// An invalid UTF-8 name on a selected route fails the whole scoped export
349	// under the full export's encoding rule, naming the offending bytes and
350	// returning no document.
351	func TestExportSourceTargetLineageRejectsInvalidUTF8OnRoute(t *testing.T) {
352		graph := buildRegisteredGraph(t, [][]string{
353			{"source"},
354			{"bad\xffmid", "source"},
355			{"report", "bad\xffmid"},
356		})
357		before := snapshotExportGraph(graph)
358	
359		out, err := ExportSourceTargetLineage(graph, "source", "report")
360		if err == nil {
361			t.Fatalf("scoped export with invalid intermediate node succeeded with %q", out)
362		}
363		if out != "" {
364			t.Errorf("failed export returned partial content %q", out)
365		}
366		if !strings.Contains(err.Error(), `"bad\xffmid"`) {
367			t.Errorf("error %q must quote the original bytes", err)
368		}
