381			t.Fatalf("invalid source exported %q", out)
382		} else if !strings.Contains(err.Error(), `"src\xff"`) {
383			t.Errorf("error %q must name the invalid source bytes", err)
384		}
385	
386		badTarget := "rep\xff"
387		graph2 := buildRegisteredGraph(t, [][]string{
388			{"source"},
