390		})
391		if out, err := ExportSourceTargetLineage(graph2, "source", badTarget); err == nil {
392			t.Fatalf("invalid target exported %q", out)
393		} else if !strings.Contains(err.Error(), `"rep\xff"`) {
394			t.Errorf("error %q must name the invalid target bytes", err)
395		}
396	
397		// Source and target identical: that node is selected (the single-node
398		// document), so its invalid name still fails the export.
399		if out, err := ExportSourceTargetLineage(graph2, badTarget, badTarget); err == nil {
400			t.Fatalf("same-name invalid endpoint exported %q", out)
401		} else if !strings.Contains(err.Error(), `"rep\xff"`) {
402			t.Errorf("error %q must name the invalid endpoint bytes", err)
403		}
404	}
405	
406	// Invalid names anywhere outside the selected routes — source's ancestor,
407	// target's independent upstream, a dead-end source downstream, target's
408	// downstream, a standalone dataset — do not block the scoped export.
409	func TestExportSourceTargetLineageIgnoresInvalidNamesOutsideRoutes(t *testing.T) {
410		graph := buildRegisteredGraph(t, [][]string{
411			{"pre\xff"},
412			{"source", "pre\xff"},
413			{"extra\xfe"},
414			{"a", "source", "extra\xfe"},
415			{"b", "source"},
416			{"mid", "b"},
417			{"sidetrack\xfd", "source"},
418			{"lone\xfc"},
419			{"report", "source", "a", "mid", "lone\xfc"},
420			{"view\xfb", "report"},
421			{"isolated\xfa"},
422		})
423	
424		out := mustExportScoped(t, graph, "source", "report")
425		doc := parseExport(t, out)
426		if !reflect.DeepEqual(doc.Nodes, scopedWantNodes) {
427			t.Errorf("nodes = %v, want %v", doc.Nodes, scopedWantNodes)
428		}
429		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, scopedWantEdges) {
430			t.Errorf("edges = %v, want %v", got, scopedWantEdges)
431		}
432	
433		// The same graph's full upstream export of report must still fail on
434		// report's invalid independent upstream, proving the scoped export judges
435		// only its own selected set.
436		if full, err := ExportUpstreamLineage(graph, "report"); err == nil {
437			t.Errorf("full export unexpectedly succeeded with %q, want an encoding error", full)
438		}
439	}
440	
441	// When several selected names are invalid, the string-smallest one is
442	// reported identically under reversed registration and upstream-list orders.
443	func TestExportSourceTargetLineageFirstInvalidNameOrderIndependent(t *testing.T) {
444		fe := "x\xfe"
445		ff := "x\xff"
446		first := buildRegisteredGraph(t, [][]string{
447			{"source"},
448			{fe, "source"},
449			{ff, "source"},
450			{"report", fe, ff},
451		})
452		second := buildRegisteredGraph(t, [][]string{
453			{"source"},
454			{ff, "source"},
455			{fe, "source"},
456			{"report", ff, fe},
457		})
458	
459		_, err1 := ExportSourceTargetLineage(first, "source", "report")
460		_, err2 := ExportSourceTargetLineage(second, "source", "report")
461		if err1 == nil || err2 == nil {
462			t.Fatalf("exports with invalid route nodes must fail, got %v and %v", err1, err2)
463		}
464		if err1.Error() != err2.Error() {
465			t.Errorf("error depends on registration/list order:\nfirst:  %q\nsecond: %q", err1, err2)
466		}
467		if !strings.Contains(err1.Error(), `"x\xfe"`) {
468			t.Errorf("error %q must report the string-smallest invalid name x\\xfe", err1)
469		}
470	}
471	
472	// Missing-name and not-found checks keep priority over encoding validation,
473	// even while the graph holds invalid names.
474	func TestExportSourceTargetLineageErrorPrecedence(t *testing.T) {
475		graph := buildRegisteredGraph(t, [][]string{
476			{"bad\xff"},
477			{"good", "bad\xff"},
478		})
479		for _, tc := range []struct {
480			source  string
481			target  string
482			wantErr string
483		}{
484			{"", "good", "dataset name is required"},
485			{"ghost", "good", "dataset not found: ghost"},
486			{"bad\xff", "", "dataset name is required"},
487			{"bad\xff", "ghost", "dataset not found: ghost"},
488		} {
489			out, err := ExportSourceTargetLineage(graph, tc.source, tc.target)
490			if err == nil {
491				t.Fatalf("(%q, %q) succeeded with %q", tc.source, tc.target, out)
492			}
493			if err.Error() != tc.wantErr {
494				t.Errorf("(%q, %q): error = %q, want %q", tc.source, tc.target, err, tc.wantErr)
495			}
496			if out != "" {
497				t.Errorf("failure returned partial content %q", out)
498			}
499		}
500	}
501	
502	// Success and failure alike leave nodes, both edge directions and list order
503	// untouched.
504	func TestExportSourceTargetLineageReadOnly(t *testing.T) {
505		graph := scopedFixture(t)
506		before := snapshotExportGraph(graph)
507	
508		mustExportScoped(t, graph, "source", "report")
509		mustExportScoped(t, graph, "source", "source")
510		mustExportScoped(t, graph, "source", "sidetrack") // empty result
511		if _, err := ExportSourceTargetLineage(graph, "ghost", "report"); err == nil {
512			t.Fatal("expected a not-found error for the source")
513		}
514		if _, err := ExportSourceTargetLineage(graph, "source", "ghost"); err == nil {
515			t.Fatal("expected a not-found error for the target")
516		}
517		assertGraphUnchanged(t, before, graph)
518	}
519	
520	// A valid unusual name on the selected routes round-trips exactly.
521	func TestExportSourceTargetLineageRoundTripsUnusualValidNames(t *testing.T) {
522		emoji := "source 🚀"
523		quote := `report "x"`
524		graph := buildRegisteredGraph(t, [][]string{
525			{emoji},
526			{"mid", emoji},
527			{quote, "mid"},
