531		wantNodes := []string{emoji, "mid", quote}
532		sort.Strings(wantNodes) // the export's own ordering rule
533		if !reflect.DeepEqual(doc.Nodes, wantNodes) {
534			t.Errorf("nodes = %q, want %q", doc.Nodes, wantNodes)
535		}
536		if got := exportEdgeNames(doc); !reflect.DeepEqual(got, [][2]string{
