11	// This file is the bidirectional regression guard for the two lineage queries:
12	// Impacts (source -> derived datasets) and Upstreams (derived dataset ->
13	// sources). They are opposite views of the very same registered parent edges,
14	// so for two distinct registered datasets u and v the relation v derives from
15	// u must read identically from either side: the dataset is listed in both
16	// directions or in neither, the Distance is the same edge count, and the Path
17	// is the very same name sequence written from the source to the derived data.
18	
19	// lineageTestOracle is an independent witness for both lineage queries. It
20	// re-derives reachability, shortest edge counts and the lexicographically
21	// smallest shortest path directly from the stored parent edges by enumerating
22	// simple walks, without calling Impacts, Upstreams or any production
23	// traversal. Register rejects cycles, so simple-walk enumeration terminates.
24	type lineageTestOracle struct {
25		children map[string][]string
26	}
27	
28	func newLineageTestOracle(t *testing.T, graph map[string]*Lineage) *lineageTestOracle {
29		t.Helper()
30		o := &lineageTestOracle{children: map[string][]string{}}
31		for name := range graph {
32			o.children[name] = nil
33		}
34		for name, entry := range graph {
35			for _, parent := range entry.Parents {
36				if _, ok := graph[parent]; !ok {
37					t.Fatalf("oracle setup: %s lists unregistered parent %s", name, parent)
38				}
39				o.children[parent] = append(o.children[parent], name)
40			}
41		}
42		return o
43	}
44	
45	// shortest answers whether from derives to along registered parent edges and,
46	// when it does, the minimum edge count and the lexicographically smallest
47	// shortest path written from `from` to `to`, including both ends.
48	func (o *lineageTestOracle) shortest(from, to string) (int, []string, bool) {
49		var walks [][]string
50		seen := map[string]bool{from: true}
51		var walk func(path []string)
52		walk = func(path []string) {
53			cur := path[len(path)-1]
54			if cur == to {
55				walks = append(walks, append([]string(nil), path...))
56				return
57			}
58			for _, next := range o.children[cur] {
59				if seen[next] {
60					continue
61				}
62				seen[next] = true
63				walk(append(path, next))
64				delete(seen, next)
65			}
66		}
67		walk([]string{from})
68		if len(walks) == 0 {
69			return 0, nil, false
70		}
71		shortestLength := len(walks[0])
72		for _, p := range walks[1:] {
73			if len(p) < shortestLength {
74				shortestLength = len(p)
75			}
76		}
77		var candidates [][]string
78		for _, p := range walks {
79			if len(p) == shortestLength {
80				candidates = append(candidates, p)
81			}
82		}
83		chosen := slices.MinFunc(candidates, slices.Compare)
84		return shortestLength - 1, append([]string(nil), chosen...), true
85	}
86	
87	func sortedGraphNames(graph map[string]*Lineage) []string {
88		names := make([]string, 0, len(graph))
89		for name := range graph {
90			names = append(names, name)
91		}
92		sort.Strings(names)
93		return names
94	}
95	
96	// assertPathEdgesRegistered checks every hop of an explanation path against
97	// the graph: adjacent names must be registered datasets linked by a parent
98	// edge (the earlier name is a direct upstream of the later one).
99	func assertPathEdgesRegistered(t *testing.T, graph map[string]*Lineage, path []string) {
100		t.Helper()
101		if len(path) == 0 {
102			t.Fatal("explanation path is empty")
103		}
104		for i := 0; i+1 < len(path); i++ {
105			child, ok := graph[path[i+1]]
106			if !ok {
107				t.Fatalf("path %v names unregistered dataset %s", path, path[i+1])
108			}
109			if !slices.Contains(child.Parents, path[i]) {
110				t.Fatalf("path %v claims the unregistered dependency %s -> %s", path, path[i], path[i+1])
111			}
112		}
113	}
114	
115	// assertImpactListShape enforces the presentation contract shared by both
116	// queries on a downstream result: non-nil list, no self row, no duplicates,
117	// distance-ascending then name ordering, and well-formed registered-edge paths.
118	func assertImpactListShape(t *testing.T, graph map[string]*Lineage, origin string, got []Impact) {
119		t.Helper()
120		if got == nil {
121			t.Fatalf("Impacts(%s) returned nil", origin)
122		}
123		listed := map[string]bool{}
124		for i, im := range got {
125			if im.Dataset == origin {
126				t.Fatalf("Impacts(%s) lists the origin itself", origin)
127			}
128			if listed[im.Dataset] {
129				t.Fatalf("Impacts(%s) lists %s more than once", origin, im.Dataset)
130			}
131			listed[im.Dataset] = true
132			if len(im.Path) != im.Distance+1 {
133				t.Fatalf("Impacts(%s) record %v: path edges %d do not match distance %d",
134					origin, im, len(im.Path)-1, im.Distance)
135			}
136			if im.Path[0] != origin || im.Path[len(im.Path)-1] != im.Dataset {
137				t.Fatalf("Impacts(%s) record %v must run from the origin to the dataset, inclusive",
138					origin, im)
139			}
140			assertPathEdgesRegistered(t, graph, im.Path)
141			if i > 0 {
142				prev := got[i-1]
143				if prev.Distance > im.Distance ||
144					(prev.Distance == im.Distance && prev.Dataset >= im.Dataset) {
145					t.Fatalf("Impacts(%s) order violation at %d: %v comes before %v",
146						origin, i, prev, im)
147				}
148			}
149		}
150	}
151	
152	// assertUpstreamListShape is the provenance-side counterpart: the path runs
153	// from the listed source to the queried target, inclusive.
154	func assertUpstreamListShape(t *testing.T, graph map[string]*Lineage, target string, got []Upstream) {
155		t.Helper()
156		if got == nil {
157			t.Fatalf("Upstreams(%s) returned nil", target)
158		}
159		listed := map[string]bool{}
160		for i, up := range got {
161			if up.Dataset == target {
162				t.Fatalf("Upstreams(%s) lists the target itself", target)
163			}
164			if listed[up.Dataset] {
165				t.Fatalf("Upstreams(%s) lists %s more than once", target, up.Dataset)
166			}
167			listed[up.Dataset] = true
168			if len(up.Path) != up.Distance+1 {
169				t.Fatalf("Upstreams(%s) record %v: path edges %d do not match distance %d",
170					target, up, len(up.Path)-1, up.Distance)
171			}
172			if up.Path[0] != up.Dataset || up.Path[len(up.Path)-1] != target {
173				t.Fatalf("Upstreams(%s) record %v must run from the source to the target, inclusive",
174					target, up)
175			}
176			assertPathEdgesRegistered(t, graph, up.Path)
177			if i > 0 {
178				prev := got[i-1]
179				if prev.Distance > up.Distance ||
180					(prev.Distance == up.Distance && prev.Dataset >= up.Dataset) {
181					t.Fatalf("Upstreams(%s) order violation at %d: %v comes before %v",
182						target, i, prev, up)
183				}
184			}
185		}
186	}
187	
188	// assertDirectionsCorrespond is the core guard: for every ordered pair of
189	// distinct registered datasets (u, v), v appears in Impacts(u) exactly when u
190	// appears in Upstreams(v), and the two rows agree on distance and on the full
191	// source-to-derived path. Membership is additionally cross-checked against the
192	// independent oracle.
193	func assertDirectionsCorrespond(t *testing.T, graph map[string]*Lineage, names []string, oracle *lineageTestOracle) {
194		t.Helper()
195		down := make(map[string]map[string]Impact, len(names))
196		up := make(map[string]map[string]Upstream, len(names))
197		for _, n := range names {
198			impacts := mustImpacts(t, graph, n)
199			upstreams := mustUpstreams(t, graph, n)
200			assertImpactListShape(t, graph, n, impacts)
201			assertUpstreamListShape(t, graph, n, upstreams)
202			down[n] = make(map[string]Impact, len(impacts))
203			for _, im := range impacts {
204				down[n][im.Dataset] = im
205			}
206			up[n] = make(map[string]Upstream, len(upstreams))
207			for _, um := range upstreams {
208				up[n][um.Dataset] = um
209			}
210		}
211	
212		for _, u := range names {
213			for _, v := range names {
214				if u == v {
215					continue
216				}
217				dr, downOK := down[u][v]
218				ur, upOK := up[v][u]
219				wantDistance, wantPath, reachable := oracle.shortest(u, v)
220	
221				if downOK != upOK {
222					t.Fatalf("directions disagree on %s -> %s: Impacts lists it = %v, Upstreams(%s) lists %s = %v",
223						u, v, downOK, v, u, upOK)
224				}
225				if downOK != reachable {
226					t.Fatalf("Impacts(%s) lists %s = %v, but the registered edges reach it = %v",
227						u, v, downOK, reachable)
228				}
229				if !reachable {
230					continue
231				}
232				if dr.Distance != wantDistance || ur.Distance != wantDistance {
233					t.Fatalf("%s -> %s distances disagree: Impacts %d, Upstreams %d, oracle %d",
234						u, v, dr.Distance, ur.Distance, wantDistance)
235				}
236				if dr.Distance != ur.Distance {
237					t.Fatalf("%s -> %s: distance seen from downstream (%d) and upstream (%d) must be equal",
238						u, v, dr.Distance, ur.Distance)
239				}
240				if !reflect.DeepEqual(dr.Path, wantPath) {
241					t.Fatalf("%s -> %s: Impacts path %v, want %v", u, v, dr.Path, wantPath)
242				}
243				if !reflect.DeepEqual(ur.Path, wantPath) {
244					t.Fatalf("%s -> %s: Upstreams(%s) path for %s is %v, want %v",
245						u, v, v, u, ur.Path, wantPath)
246				}
247				if !reflect.DeepEqual(dr.Path, ur.Path) {
248					t.Fatalf("%s -> %s: the two directions explain one dependency with different paths %v vs %v",
249						u, v, dr.Path, ur.Path)
250				}
251			}
252		}
253	}
