297	// layeredCorrespondenceRegistrations builds a graph spanning direct and
298	// multi-level (up to five edges) relationships, diamonds, merges where the
299	// branches arrive at different depths, a merge whose equal-length routes are
300	// decided by the full path rather than the merge node's direct-upstream order,
301	// two disconnected components and fully isolated datasets:
302	//
303	//	root -> a -> z ------> m ----\
304	//	  \      \-> long ---/  \     \
305	//	   \      \-> q -> merge2 -> tip -> leaf
306	//	    \-> b -> c ------/^  (merge2 also takes q at one level less)
307	//	tip also takes long at the same depth as merge2.
308	//	r2 -> d1 -> d2 is a separate component; iso and solo are isolated.
309	func layeredCorrespondenceRegistrations() [][]string {
310		return [][]string{
311			{"root"},
312			{"r2"},
313			{"iso"},
314			{"solo"},
315			{"a", "root"},
316			{"b", "root"},
317			{"z", "a"},
318			{"c", "b"},
319			{"q", "a"},
320			{"m", "c", "z"}, // c listed before z on purpose: c < z at the merge
321			{"long", "z"},
322			{"merge2", "m", "q"},
323			{"d1", "r2"},
324			{"d2", "d1"},
325			{"tip", "merge2", "long"},
326			{"leaf", "tip"},
327		}
328	}
329	
330	// Whole-graph regression: both queries for every registered node agree with
331	// each other and with an independent shortest-path oracle, across direct and
332	// multi-level relations, branch merges and disconnected components.
333	func TestImpactsUpstreamsCorrespondenceAcrossLayeredGraph(t *testing.T) {
334		graph := buildRegisteredGraph(t, layeredCorrespondenceRegistrations())
335		assertConsistent(t, graph)
336		names := sortedGraphNames(graph)
337		oracle := newLineageTestOracle(t, graph)
338		before := snapshot(graph)
339	
340		for _, n := range names {
341			impacts := mustImpacts(t, graph, n)
342			assertImpactListShape(t, graph, n, impacts)
343			if want := expectedImpacts(names, oracle, n); !reflect.DeepEqual(impacts, want) {
344				t.Fatalf("Impacts(%s) = %v, want %v", n, impacts, want)
345			}
346	
347			upstreams := mustUpstreams(t, graph, n)
348			assertUpstreamListShape(t, graph, n, upstreams)
349			if want := expectedUpstreams(names, oracle, n); !reflect.DeepEqual(upstreams, want) {
350				t.Fatalf("Upstreams(%s) = %v, want %v", n, upstreams, want)
351			}
352		}
353	
354		// Every related pair is witnessed identically from both directions, and no
355		// unrelated pair in either direction.
356		assertDirectionsCorrespond(t, graph, names, oracle)
357	
358		// Explicit anchors at the tricky merges.
359	
360		// m is reached over two equal three-edge routes, root->a->z->m and
361		// root->b->c->m. Comparing only m's direct upstreams would wrongly pick the
362		// c route (c < z); the full-path rule first differs at hop 1 where a < b, so
363		// both directions explain m through a and z.
364		impacts := mustImpacts(t, graph, "root")
365		assertImpactOnce(t, impacts, "m", 3, []string{"root", "a", "z", "m"})
366		upstreams := mustUpstreams(t, graph, "m")
367		assertUpstreamOnce(t, upstreams, "root", 3, []string{"root", "a", "z", "m"})
368	
369		// merge2 takes m (depth 3) and q (depth 2): the q route is one edge shorter
370		// and wins from both sides regardless of list order.
371		assertImpactOnce(t, impacts, "merge2", 3, []string{"root", "a", "q", "merge2"})
372		assertUpstreamOnce(t, mustUpstreams(t, graph, "merge2"), "root", 3,
373			[]string{"root", "a", "q", "merge2"})
374	
375		// tip merges merge2 and long, both at depth 3. Its two four-edge routes are
376		// root->a->q->merge2->tip and root->a->z->long->tip; they first differ at
377		// hop 2 where q < z, so the merge2 route explains tip and continues into leaf.
378		assertImpactOnce(t, impacts, "tip", 4, []string{"root", "a", "q", "merge2", "tip"})
379		assertImpactOnce(t, impacts, "leaf", 5, []string{"root", "a", "q", "merge2", "tip", "leaf"})
380		tipUpstreams := mustUpstreams(t, graph, "tip")
381		assertUpstreamOnce(t, tipUpstreams, "root", 4, []string{"root", "a", "q", "merge2", "tip"})
382		assertUpstreamOnce(t, mustUpstreams(t, graph, "leaf"), "root", 5,
383			[]string{"root", "a", "q", "merge2", "tip", "leaf"})
384	
385		// Branch intermediates keep their own, distinct explanations instead of
386		// borrowing the merge node's route.
387		assertImpactOnce(t, impacts, "z", 2, []string{"root", "a", "z"})
388		assertImpactOnce(t, impacts, "c", 2, []string{"root", "b", "c"})
389		assertImpactOnce(t, impacts, "long", 3, []string{"root", "a", "z", "long"})
390		assertUpstreamOnce(t, tipUpstreams, "long", 1, []string{"long", "tip"})
391		assertUpstreamOnce(t, tipUpstreams, "merge2", 1, []string{"merge2", "tip"})
392		assertUpstreamOnce(t, tipUpstreams, "q", 2, []string{"q", "merge2", "tip"})
393		assertUpstreamOnce(t, tipUpstreams, "z", 2, []string{"z", "long", "tip"})
394	
395		// Direct relations at every level are present on both sides with equal rows.
396		assertImpactOnce(t, impacts, "a", 1, []string{"root", "a"})
397		assertImpactOnce(t, impacts, "b", 1, []string{"root", "b"})
398		assertUpstream(t, mustUpstreams(t, graph, "z"), "a", 1, []string{"a", "z"})
399		assertUpstream(t, mustUpstreams(t, graph, "leaf"), "tip", 1, []string{"tip", "leaf"})
400	
401		// The two components and the isolated datasets must never be related in
402		// either direction, while each component stays internally consistent.
403		r2Impacts := mustImpacts(t, graph, "r2")
404		if got, want := impactNames(r2Impacts), []string{"d1", "d2"}; !reflect.DeepEqual(got, want) {
405			t.Fatalf("Impacts(r2) = %v, want only its own component %v", got, want)
406		}
407		assertImpact(t, r2Impacts, "d2", 2, []string{"r2", "d1", "d2"})
408		d2Upstreams := mustUpstreams(t, graph, "d2")
409		if got, want := upstreamNames(d2Upstreams), []string{"d1", "r2"}; !reflect.DeepEqual(got, want) {
410			t.Fatalf("Upstreams(d2) = %v, want only its own component %v", got, want)
411		}
412		assertUpstream(t, d2Upstreams, "r2", 2, []string{"r2", "d1", "d2"})
413		for _, across := range [][2]string{
414			{"root", "r2"}, {"root", "d2"}, {"a", "d1"}, {"m", "d2"},
415			{"r2", "leaf"}, {"iso", "root"}, {"solo", "tip"}, {"d1", "iso"},
416		} {
417			if _, ok := downRecord(mustImpacts(t, graph, across[0]), across[1]); ok {
418				t.Fatalf("%s must not list unrelated %s downstream", across[0], across[1])
419			}
420			if _, ok := upRecord(mustUpstreams(t, graph, across[1]), across[0]); ok {
421				t.Fatalf("%s must not list unrelated %s upstream", across[1], across[0])
422			}
423		}
424	
425		// Registered nodes with no relation in a direction answer with a non-nil
426		// empty list rather than an error or a nil slice.
427		for _, leafName := range []string{"leaf", "d2", "iso", "solo"} {
428			got := mustImpacts(t, graph, leafName)
429			if got == nil || len(got) != 0 {
430				t.Fatalf("Impacts(%s) = %v, want non-nil empty list", leafName, got)
431			}
432		}
433		for _, rootName := range []string{"root", "r2", "iso", "solo"} {
434			got := mustUpstreams(t, graph, rootName)
435			if got == nil || len(got) != 0 {
436				t.Fatalf("Upstreams(%s) = %v, want non-nil empty list", rootName, got)
437			}
438		}
439	
440		// Unregistered names fail in both directions, the error names the dataset
441		// and the result is nil; an empty name is a missing-name error.
442		if got, err := Impacts(graph, "ghost"); err == nil ||
443			!strings.Contains(err.Error(), "ghost") || got != nil {
444			t.Fatalf("Impacts(ghost): want naming error and nil, got %v, %v", got, err)
445		}
446		if got, err := Upstreams(graph, "ghost"); err == nil ||
447			!strings.Contains(err.Error(), "ghost") || got != nil {
448			t.Fatalf("Upstreams(ghost): want naming error and nil, got %v, %v", got, err)
449		}
450		if got, err := Impacts(graph, ""); err == nil ||
451			!strings.Contains(err.Error(), "name is required") || got != nil {
452			t.Fatalf("Impacts(empty): want required-name error and nil, got %v, %v", got, err)
453		}
454		if got, err := Upstreams(graph, ""); err == nil ||
455			!strings.Contains(err.Error(), "name is required") || got != nil {
456			t.Fatalf("Upstreams(empty): want required-name error and nil, got %v, %v", got, err)
457		}
458		if got, err := Impacts(map[string]*Lineage{}, "ghost"); err == nil || got != nil ||
459			!strings.Contains(err.Error(), "ghost") {
460			t.Fatalf("Impacts on empty graph: want naming error and nil, got %v, %v", got, err)
461		}
462		if got, err := Upstreams(nil, "ghost"); err == nil || got != nil ||
463			!strings.Contains(err.Error(), "ghost") {
464			t.Fatalf("Upstreams on nil graph: want naming error and nil, got %v, %v", got, err)
465		}
466	
467		// All queries together leave nodes, relationships and stored list order as
468		// they were before and after.
469		if !reflect.DeepEqual(snapshot(graph), before) {
470			t.Fatalf("queries changed the graph: before=%v after=%v", before, snapshot(graph))
471		}
472		assertConsistent(t, graph)
473	}
474	
475	func downRecord(impacts []Impact, name string) (Impact, bool) {
476		for _, im := range impacts {
477			if im.Dataset == name {
478				return im, true
479			}
480		}
481		return Impact{}, false
482	}
483	
484	func upRecord(upstreams []Upstream, name string) (Upstream, bool) {
485		for _, up := range upstreams {
486			if up.Dataset == name {
487				return up, true
488			}
489		}
490		return Upstream{}, false
491	}
492	
493	// Focused merge regression exercised simultaneously from both directions.
494	// source feeds a and b; a feeds z and d1; b feeds c; report depends on c and z
495	// (c declared first); view derives report; d1 -> d2 and win depends on d2 and b
496	// together; iso stands alone.
497	//
498	//	report: source->a->z->report vs source->b->c->report, equal length. The
499	//	        merge node's own direct-upstream order prefers c (c < z), but the
500	//	        full path first differs at hop 1 (a < b): both queries must choose
501	//	        the a/z route.
502	//	win:    source->b->win is two edges; source->a->d1->d2->win is four edges
503	//	        and is lexicographically smaller at hop 1 (a < b) but longer, so the
504	//	        shorter b route must win from both queries.
505	func TestImpactsUpstreamsMergedBranchesAgreeFromBothDirections(t *testing.T) {
506		build := func() map[string]*Lineage {
507			return buildRegisteredGraph(t, [][]string{
508				{"source"},
509				{"a", "source"},
510				{"b", "source"},
511				{"z", "a"},
512				{"c", "b"},
513				{"report", "c", "z"}, // c ahead of z on purpose
514				{"view", "report"},
515				{"d1", "a"},
516				{"d2", "d1"},
517				{"win", "d2", "b"}, // equal parents ordered against the short-route name
518				{"iso"},
519			})
520		}
521	
522		graph := build()
523		assertConsistent(t, graph)
524		names := sortedGraphNames(graph)
525		oracle := newLineageTestOracle(t, graph)
526		before := snapshot(graph)
527	
528		impacts := mustImpacts(t, graph, "source")
529		wantImpacts := []Impact{
530			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
531			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
532			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
533			{Dataset: "d1", Distance: 2, Path: []string{"source", "a", "d1"}},
534			{Dataset: "win", Distance: 2, Path: []string{"source", "b", "win"}},
535			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
536			{Dataset: "d2", Distance: 3, Path: []string{"source", "a", "d1", "d2"}},
537			{Dataset: "report", Distance: 3, Path: []string{"source", "a", "z", "report"}},
538			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
539		}
540		if !reflect.DeepEqual(impacts, wantImpacts) {
541			t.Fatalf("Impacts(source) = %v, want %v", impacts, wantImpacts)
542		}
543	
544		upstreams := mustUpstreams(t, graph, "report")
545		wantUpstreams := []Upstream{
546			{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
547			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
548			{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
549			{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
550			{Dataset: "source", Distance: 3, Path: []string{"source", "a", "z", "report"}},
551		}
552		if !reflect.DeepEqual(upstreams, wantUpstreams) {
553			t.Fatalf("Upstreams(report) = %v, want %v", upstreams, wantUpstreams)
554		}
555	
556		// The single shared source->report dependency must read identically from
557		// either query: same distance, same full explanation path.
558		downRow, downOK := downRecord(impacts, "report")
559		upRow, upOK := upRecord(upstreams, "source")
560		if !downOK || !upOK {
561			t.Fatalf("the relation is missing from one side: Impacts=%v Upstreams=%v", downOK, upOK)
562		}
563		if downRow.Distance != upRow.Distance || !reflect.DeepEqual(downRow.Path, upRow.Path) {
564			t.Fatalf("source->report explained differently: downstream %v vs upstream %v", downRow, upRow)
565		}
566		if got, want := downRow.Path, []string{"source", "a", "z", "report"}; !reflect.DeepEqual(got, want) {
567			t.Fatalf("merge path = %v, want %v (full path a<b must beat merge-local c<z)", got, want)
568		}
569	
570		// win's shorter b route beats the lexicographically smaller a route from
571		// both directions, and both sides report the exact same row.
572		assertImpactOnce(t, impacts, "win", 2, []string{"source", "b", "win"})
573		winUpstreams := mustUpstreams(t, graph, "win")
574		wantWinUpstreams := []Upstream{
575			{Dataset: "b", Distance: 1, Path: []string{"b", "win"}},
576			{Dataset: "d2", Distance: 1, Path: []string{"d2", "win"}},
577			{Dataset: "d1", Distance: 2, Path: []string{"d1", "d2", "win"}},
578			{Dataset: "source", Distance: 2, Path: []string{"source", "b", "win"}},
579			{Dataset: "a", Distance: 3, Path: []string{"a", "d1", "d2", "win"}},
580		}
581		if !reflect.DeepEqual(winUpstreams, wantWinUpstreams) {
582			t.Fatalf("Upstreams(win) = %v, want %v", winUpstreams, wantWinUpstreams)
583		}
584		winDown, _ := downRecord(impacts, "win")
585		winUp, _ := upRecord(winUpstreams, "source")
586		if winDown.Distance != 2 || winUp.Distance != 2 ||
587			!reflect.DeepEqual(winDown.Path, []string{"source", "b", "win"}) ||
588			!reflect.DeepEqual(winUp.Path, []string{"source", "b", "win"}) {
589			t.Fatalf("win's longer a-first route must not replace the shorter b route: down=%v up=%v",
590				winDown, winUp)
591		}
592	
593		// Branch intermediates keep their own correct rows on both sides despite
594		// sharing source with each other and report as their merge point: none is
595		// missing, duplicated, or explained through another pair's route.
596		for _, want := range []Impact{
597			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
598			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
599			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
600			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
601			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
602		} {
603			assertImpactOnce(t, impacts, want.Dataset, want.Distance, want.Path)
604		}
605		for _, want := range []Upstream{
606			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
607			{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
608			{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
609			{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
610		} {
611			assertUpstreamOnce(t, upstreams, want.Dataset, want.Distance, want.Path)
612		}
613		// view inherits report's merge explanation; source reaches it only through
614		// report, and the row matches the downstream side exactly.
615		assertUpstreamOnce(t, mustUpstreams(t, graph, "view"), "source", 4,
616			[]string{"source", "a", "z", "report", "view"})
617	
618		// The isolated dataset is related to nothing in either direction.
619		if slices.Contains(impactNames(impacts), "iso") {
620			t.Fatalf("iso leaked into Impacts(source): %v", impactNames(impacts))
621		}
622		if slices.Contains(upstreamNames(upstreams), "iso") {
623			t.Fatalf("iso leaked into Upstreams(report): %v", upstreamNames(upstreams))
624		}
625		isoDown := mustImpacts(t, graph, "iso")
626		isoUp := mustUpstreams(t, graph, "iso")
627		if isoDown == nil || len(isoDown) != 0 || isoUp == nil || len(isoUp) != 0 {
628			t.Fatalf("iso queries must be non-nil empty, got down=%v up=%v", isoDown, isoUp)
629		}
630	
631		// Full pairwise correspondence guard for this graph too.
632		assertDirectionsCorrespond(t, graph, names, oracle)
633		if !reflect.DeepEqual(snapshot(graph), before) {
634			t.Fatalf("queries changed the graph: before=%v after=%v", before, snapshot(graph))
635		}
636	
637		// Adding the direct source->report edge makes edge count win outright: the
638		// three-edge a/z route must disappear from both sides even though it is
639		// lexicographically smaller, and the new edge's position in report's
640		// declared list must not change anything.
641		for _, parents := range [][]string{
642			{"source", "c", "z"},
643			{"z", "c", "source"},
644			{"c", "source", "z"},
645		} {
646			mustRegister(t, graph, "report", parents...)
647			assertConsistent(t, graph)
648	
649			impacts = mustImpacts(t, graph, "source")
650			wantImpacts = []Impact{
651				{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
652				{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
653				{Dataset: "report", Distance: 1, Path: []string{"source", "report"}},
654				{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
655				{Dataset: "d1", Distance: 2, Path: []string{"source", "a", "d1"}},
656				{Dataset: "view", Distance: 2, Path: []string{"source", "report", "view"}},
657				{Dataset: "win", Distance: 2, Path: []string{"source", "b", "win"}},
658				{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
659				{Dataset: "d2", Distance: 3, Path: []string{"source", "a", "d1", "d2"}},
660			}
661			if !reflect.DeepEqual(impacts, wantImpacts) {
662				t.Fatalf("parents %v: Impacts(source) = %v, want %v", parents, impacts, wantImpacts)
663			}
664			upstreams = mustUpstreams(t, graph, "report")
665			wantUpstreams = []Upstream{
666				{Dataset: "c", Distance: 1, Path: []string{"c", "report"}},
667				{Dataset: "source", Distance: 1, Path: []string{"source", "report"}},
668				{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
669				{Dataset: "a", Distance: 2, Path: []string{"a", "z", "report"}},
670				{Dataset: "b", Distance: 2, Path: []string{"b", "c", "report"}},
671			}
672			if !reflect.DeepEqual(upstreams, wantUpstreams) {
673				t.Fatalf("parents %v: Upstreams(report) = %v, want %v", parents, upstreams, wantUpstreams)
674			}
675			assertImpactOnce(t, impacts, "report", 1, []string{"source", "report"})
676			assertImpactOnce(t, impacts, "view", 2, []string{"source", "report", "view"})
677			assertUpstreamOnce(t, upstreams, "source", 1, []string{"source", "report"})
678	
679			// Same dependency, identical row from both directions; the unrelated win
680			// merge and its own explanation are untouched.
681			downRow, _ = downRecord(impacts, "report")
682			upRow, _ = upRecord(upstreams, "source")
683			if downRow.Distance != upRow.Distance || !reflect.DeepEqual(downRow.Path, upRow.Path) {
684				t.Fatalf("parents %v: source->report rows diverge: %v vs %v", parents, downRow, upRow)
685			}
686			assertImpactOnce(t, impacts, "win", 2, []string{"source", "b", "win"})
687			assertDirectionsCorrespond(t, graph, names, newLineageTestOracle(t, graph))
688		}
689	}
690	
691	// parentEdgeSet flattens the final registered dependencies as unordered pairs
692	// [child, parent], so two builds with different registration or list orders
693	// can be compared on relationships alone.
694	func parentEdgeSet(graph map[string]*Lineage) map[[2]string]bool {
695		edges := map[[2]string]bool{}
696		for name, entry := range graph {
697			for _, parent := range entry.Parents {
698				edges[[2]string{name, parent}] = true
699			}
700		}
701		return edges
702	}
703	
704	// The same final lineage built through different legal registration orders and
705	// with differently ordered direct-upstream lists must yield identical
706	// relations, distances and explanation paths in both directions, for every
707	// registered dataset.
708	func TestImpactsUpstreamsIndependentOfRegistrationOrder(t *testing.T) {
709		sequences := [][][]string{
710			// Baseline: one component top-down, the other early, merge parents in
711			// non-name order.
712			layeredCorrespondenceRegistrations(),
713			// Second component first, branches reversed, every merge's parent list
714			// flipped, roots iso/solo registered last.
715			{
716				{"r2"},
717				{"d1", "r2"},
718				{"d2", "d1"},
719				{"root"},
720				{"b", "root"},
721				{"c", "b"},
722				{"a", "root"},
723				{"z", "a"},
724				{"q", "a"},
725				{"long", "z"},
726				{"m", "z", "c"},
727				{"merge2", "q", "m"},
728				{"tip", "long", "merge2"},
729				{"leaf", "tip"},
730				{"iso"},
731				{"solo"},
732			},
733			// Roots first, middle layer interleaved across components, parent lists
734			// mixed yet differently again.
735			{
736				{"iso"},
737				{"root"},
738				{"r2"},
739				{"solo"},
740				{"a", "root"},
741				{"z", "a"},
742				{"b", "root"},
743				{"c", "b"},
744				{"d1", "r2"},
745				{"long", "z"},
746				{"m", "z", "c"},
747				{"q", "a"},
748				{"merge2", "m", "q"},
749				{"d2", "d1"},
750				{"tip", "merge2", "long"},
751				{"leaf", "tip"},
752			},
753		}
754	
755		graphs := make([]map[string]*Lineage, len(sequences))
756		for i, seq := range sequences {
757			graphs[i] = buildRegisteredGraph(t, seq)
758			assertConsistent(t, graphs[i])
759		}
760	
761		base := graphs[0]
762		baseNames := sortedGraphNames(base)
763		baseEdges := parentEdgeSet(base)
764		for gi := 1; gi < len(graphs); gi++ {
765			g := graphs[gi]
766			if got := parentEdgeSet(g); !reflect.DeepEqual(got, baseEdges) {
767				t.Fatalf("build %d relationships differ: got %v want %v", gi, got, baseEdges)
768			}
769			if names := sortedGraphNames(g); !reflect.DeepEqual(names, baseNames) {
770				t.Fatalf("build %d datasets differ: got %v want %v", gi, names, baseNames)
771			}
772		}
773	
774		// Identical relationships imply identical complete query answers, node by
775		// node, in both directions — ordering included.
776		for _, name := range baseNames {
777			wantDown := mustImpacts(t, base, name)
778			wantUp := mustUpstreams(t, base, name)
779			for gi := 1; gi < len(graphs); gi++ {
780				if got := mustImpacts(t, graphs[gi], name); !reflect.DeepEqual(got, wantDown) {
781					t.Fatalf("build %d Impacts(%s) = %v, want %v", gi, name, got, wantDown)
782				}
783				if got := mustUpstreams(t, graphs[gi], name); !reflect.DeepEqual(got, wantUp) {
784					t.Fatalf("build %d Upstreams(%s) = %v, want %v", gi, name, got, wantUp)
785				}
786			}
787		}
788	
789		// Every build also passes the pairwise two-direction correspondence guard.
790		for gi, g := range graphs {
791			assertDirectionsCorrespond(t, g, sortedGraphNames(g), newLineageTestOracle(t, g))
792			if !slices.Equal(sortedGraphNames(g), baseNames) {
793				t.Fatalf("build %d dataset set changed after queries", gi)
794			}
795		}
796	}
797	
798	// Small-graph contract for the boundary cases: a registered node without a
799	// relation in a direction succeeds with a non-nil empty list and never lists
800	// itself, while unknown names fail in both directions with nil results.
801	func TestImpactsUpstreamsEmptyListsAndErrors(t *testing.T) {
802		graph := buildRegisteredGraph(t, [][]string{
803			{"lone"},
804			{"p"},
805			{"c", "p"},
806		})
807		before := snapshot(graph)
808	
809		// Registered but no downstream / no upstream: successful non-nil empties.
810		for name, query := range map[string]func() (int, error){
811			"Impacts(lone)":   func() (int, error) { r, e := Impacts(graph, "lone"); return len(r), e },
812			"Impacts(c)":      func() (int, error) { r, e := Impacts(graph, "c"); return len(r), e },
813			"Upstreams(lone)": func() (int, error) { r, e := Upstreams(graph, "lone"); return len(r), e },
814			"Upstreams(p)":    func() (int, error) { r, e := Upstreams(graph, "p"); return len(r), e },
815		} {
816			if n, err := query(); err != nil || n != 0 {
817				t.Fatalf("%s: want successful empty list, got n=%d err=%v", name, n, err)
818			}
819		}
820		down := mustImpacts(t, graph, "lone")
821		if down == nil {
822			t.Fatal("Impacts(lone) must be non-nil")
823		}
824		up := mustUpstreams(t, graph, "lone")
825		if up == nil {
826			t.Fatal("Upstreams(lone) must be non-nil")
827		}
828	
829		// The single related pair is present on both matching sides and absent from
830		// the reverse queries, with equal distance and identical paths.
831		assertImpactOnce(t, mustImpacts(t, graph, "p"), "c", 1, []string{"p", "c"})
832		assertUpstreamOnce(t, mustUpstreams(t, graph, "c"), "p", 1, []string{"p", "c"})
833		if got := mustImpacts(t, graph, "c"); len(got) != 0 {
834			t.Fatalf("Impacts(c) must not list its upstream p, got %v", got)
835		}
836		if got := mustUpstreams(t, graph, "p"); len(got) != 0 {
837			t.Fatalf("Upstreams(p) must not list its downstream c, got %v", got)
838		}
839	
840		// Unregistered and empty names in both directions. The raw result must be
841		// nil; names are only extracted on success.
842		if got, err := Impacts(graph, "ghost"); err == nil || got != nil ||
843			!strings.Contains(err.Error(), "ghost") {
844			t.Fatalf("Impacts(ghost): want naming error and nil, got %v, %v", got, err)
845		}
846		if got, err := Impacts(graph, ""); err == nil || got != nil ||
847			!strings.Contains(err.Error(), "name is required") {
848			t.Fatalf("Impacts(empty): want required-name error and nil, got %v, %v", got, err)
849		}
850		if got, err := Upstreams(graph, "ghost"); err == nil || got != nil ||
851			!strings.Contains(err.Error(), "ghost") {
852			t.Fatalf("Upstreams(ghost): want naming error and nil, got %v, %v", got, err)
853		}
854		if got, err := Upstreams(graph, ""); err == nil || got != nil ||
855			!strings.Contains(err.Error(), "name is required") {
856			t.Fatalf("Upstreams(empty): want required-name error and nil, got %v, %v", got, err)
857		}
858	
859		// Read-only: successful and failing queries leave the graph untouched.
860		if !reflect.DeepEqual(snapshot(graph), before) {
861			t.Fatalf("graph changed after boundary queries: before=%v after=%v", before, snapshot(graph))
862		}
863		assertConsistent(t, graph)
864	}
