755		}
756		if !reflect.DeepEqual(snapshot(graph), before) {
757			t.Fatalf("query changed graph: before=%v after=%v", before, snapshot(graph))
758		}
759	
760		// Abuse the returned slices, then confirm the graph is still untouched.
761		impacts[0].Path[0] = "tampered"
762		impacts[0].Path = append(impacts[0].Path, "extra")
763		impacts[0].Dataset = "tampered"
764		impacts[0].Distance = 99
765		if !reflect.DeepEqual(snapshot(graph), before) {
766			t.Fatalf("mutating results changed graph: before=%v after=%v", before, snapshot(graph))
767		}
768	
769		// A failed query is also read-only.
770		if _, err := Impacts(graph, "missing"); err == nil {
771			t.Fatal("expected not-found error")
772		}
773		if !reflect.DeepEqual(snapshot(graph), before) {
774			t.Fatalf("failed query changed graph: before=%v after=%v", before, snapshot(graph))
775		}
776		assertConsistent(t, graph)
777	}
